//! Weapon and gadget names from the embedded `data/weapons.json` table.
//!
//! Keys are game item IDs (the `weaponItemId` the patched r6-dissect reads from the killer's
//! operator loadout block), not the raw asset ID of the kill packet (`weaponId`). The table is
//! generated by `tools/gen-weapons` from wnc-replay/replay-tool `analysis/names.go` (MIT).
//! Unknown IDs give `None`; nothing is guessed.

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const WEAPONS_JSON: &str = include_str!("../../../data/weapons.json");

#[derive(Deserialize)]
struct Entry {
    name: String,
    #[serde(default)]
    kind: String,
    #[serde(default)]
    source: String,
}

struct Weapon {
    name: String,
    kind: String,
    /// `inferred` for names matched by elimination instead of read from a source table.
    source: String,
}

fn table() -> &'static HashMap<u64, Weapon> {
    static T: OnceLock<HashMap<u64, Weapon>> = OnceLock::new();
    T.get_or_init(|| match serde_json::from_str::<HashMap<String, Entry>>(WEAPONS_JSON) {
        Ok(m) => m
            .into_iter()
            .filter_map(|(id, e)| {
                let id = id.parse::<u64>().ok()?;
                Some((id, Weapon { name: e.name, kind: e.kind, source: e.source }))
            })
            .collect(),
        Err(e) => {
            log::error!("embedded weapon table is invalid: {e}");
            HashMap::new()
        }
    })
}

/// Display name for a game item ID, e.g. `R4-C`.
pub fn weapon_name(id: u64) -> Option<&'static str> {
    table().get(&id).map(|w| w.name.as_str())
}

/// Item kind from the source table: `weapon`, `ability`, `gadget`, `reinforcement`, `drone`,
/// `objective`, `equipment` or `other`.
pub fn weapon_kind(id: u64) -> Option<&'static str> {
    table().get(&id).map(|w| w.kind.as_str()).filter(|k| !k.is_empty())
}

/// True when the name of this item was inferred (`"source": "inferred"` in `data/weapons.json`).
pub fn weapon_is_inferred(id: u64) -> bool {
    table().get(&id).is_some_and(|w| w.source == "inferred")
}

/// Kill sources that are not an inventory item, keyed by the raw asset ID of the kill packet:
/// `(slot, label)`. They have no weapon slot and no loadout item.
///
/// Both come from the 30 local Y11S3 replays (1192 kills), where every kill with no slot carries one
/// of these two asset IDs: 70077334926 for Fuze (cluster charge), Thorn (razorbloom shell) and Ace
/// (S.E.L.M.A.), all non-headshot explosions; 3099101909 for Caveira, Bandit and Wamai, three
/// operators without a shared gadget, so the one damage source every operator has: melee.
/// The melee match is **inferred**, not read from a table.
const GENERIC_KILLS: [(u64, &str, &str); 2] = [
    (70077334926, "explosion", "Explosion"),
    (3099101909, "melee", "Melee"),
];

/// Slot and label of a generic (non-item) kill source, e.g. `("melee", "Melee")`.
pub fn generic_kill_source(asset: u64) -> Option<(&'static str, &'static str)> {
    GENERIC_KILLS.iter().find(|g| g.0 == asset).map(|g| (g.1, g.2))
}

/// A weapon name as the screens show it, with the stats grouping that goes with it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WeaponLabel {
    /// Name without an operator variant (`Nitro Cell`, not `Nitro Cell (Bandit)`): the stats row.
    pub name: String,
    /// Full display name; keeps the variant (`Nitro Cell (Bandit)`) for the kill feed.
    pub display: String,
    /// The item is not in the tables, so the name is an operator-and-slot label (`Noor primary`).
    pub unnamed: bool,
}

/// Title-cases a stored weapon name. The source table is mostly upper case (`416-C CARBINE`).
/// Words with a digit, short words (up to three letters: `EMP`, `SAW`, `MPX`) and words that are
/// already mixed case (`Mk`, `9mm`) stay as they are; every other upper case word gets a capital
/// first letter, also inside hyphens and parentheses.
pub fn title_case(raw: &str) -> String {
    fn word(w: &str) -> String {
        let letters: Vec<char> = w.chars().filter(|c| c.is_alphabetic()).collect();
        let has_lower = letters.iter().any(|c| c.is_lowercase());
        if letters.len() <= 3 || has_lower || w.chars().any(|c| c.is_ascii_digit()) || w.contains('.') {
            return w.to_string();
        }
        let mut out = String::new();
        let mut prev_letter = false;
        for c in w.chars() {
            if prev_letter {
                out.extend(c.to_lowercase());
            } else {
                out.extend(c.to_uppercase());
            }
            prev_letter = c.is_alphabetic();
        }
        out
    }
    raw.split_whitespace()
        .map(|tok| {
            // Split a token at hyphens and parentheses, keeping the separators.
            let mut out = String::new();
            let mut cur = String::new();
            for c in tok.chars() {
                if c == '-' || c == '(' || c == ')' {
                    out.push_str(&word(&cur));
                    cur.clear();
                    out.push(c);
                } else {
                    cur.push(c);
                }
            }
            out.push_str(&word(&cur));
            out
        })
        .collect::<Vec<_>>()
        .join(" ")
}

/// Name without a trailing operator variant: `Nitro Cell (Bandit)` gives `Nitro Cell`.
pub fn base_name(name: &str) -> &str {
    match name.rfind(" (") {
        Some(i) if name.ends_with(')') => name[..i].trim_end(),
        _ => name,
    }
}

/// Label of a stored kill weapon.
///
/// * `Unknown primary` / `Unknown gadget` ... (an item the tables do not know) becomes
///   `<Operator> primary` when `operator` is a known operator name; nothing is made up.
/// * Known names are title-cased and the operator variant is split off into [`WeaponLabel::name`].
pub fn label(raw: &str, operator: Option<&str>) -> WeaponLabel {
    if let Some(slot) = raw.strip_prefix("Unknown ") {
        return match operator {
            Some(op) if !op.is_empty() && slot != "weapon" => {
                let n = format!("{op} {slot}");
                WeaponLabel { name: n.clone(), display: n, unnamed: true }
            }
            _ => WeaponLabel { name: raw.to_string(), display: raw.to_string(), unnamed: true },
        };
    }
    let display = title_case(raw);
    WeaponLabel { name: base_name(&display).to_string(), display, unnamed: false }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_are_title_cased_and_variants_merge() {
        assert_eq!(title_case("416-C CARBINE"), "416-C Carbine");
        assert_eq!(title_case("IMPACT GRENADE"), "Impact Grenade");
        assert_eq!(title_case("SUPERNOVA"), "Supernova");
        assert_eq!(title_case("Mk 14 EBR"), "Mk 14 EBR");
        assert_eq!(title_case("R4-C"), "R4-C");
        assert_eq!(title_case("SPEC-IO ELECTRO-SENSOR"), "Spec-IO Electro-Sensor");
        assert_eq!(title_case("S.E.L.M.A."), "S.E.L.M.A.");
        assert_eq!(title_case("9x19VSN"), "9x19VSN");
        assert_eq!(title_case("Bailiff 410"), "Bailiff 410");
        let a = label("NITRO CELL (BANDIT)", Some("Bandit"));
        let b = label("NITRO CELL", None);
        assert_eq!(a.display, "Nitro Cell (Bandit)");
        assert_eq!((a.name.as_str(), b.name.as_str()), ("Nitro Cell", "Nitro Cell"));
    }

    #[test]
    fn unknown_items_are_named_by_operator_and_slot() {
        let l = label("Unknown primary", Some("Noor"));
        assert_eq!((l.name.as_str(), l.unnamed), ("Noor primary", true));
        assert_eq!(label("Unknown gadget", Some("Wamai")).name, "Wamai gadget");
        assert_eq!(label("Unknown primary", None).name, "Unknown primary");
        assert_eq!(label("Unknown weapon", Some("Noor")).name, "Unknown weapon");
        assert!(!label("Melee", Some("Noor")).unnamed);
    }

    #[test]
    fn table_loads() {
        assert!(table().len() > 500, "weapon table has {} entries", table().len());
    }

    #[test]
    fn known_ids_resolve() {
        assert_eq!(weapon_name(0x37802D177E), Some("R4-C"));
        assert_eq!(weapon_kind(0x37802D177E), Some("weapon"));
        assert_eq!(weapon_name(0x37802D1C53), Some("416-C CARBINE"));
    }

    #[test]
    fn inferred_names_are_marked() {
        assert_eq!(weapon_name(437464103147), Some("XK23"));
        assert!(weapon_is_inferred(437464103147));
        assert!(!weapon_is_inferred(0x37802D177E));
        assert_eq!(weapon_kind(238373641120), Some("gadget")); // X-KAIROS
    }

    #[test]
    fn generic_kill_sources() {
        assert_eq!(generic_kill_source(70077334926), Some(("explosion", "Explosion")));
        assert_eq!(generic_kill_source(3099101909), Some(("melee", "Melee")));
        assert_eq!(generic_kill_source(1366019316), None);
    }

    #[test]
    fn unknown_ids_are_none() {
        assert_eq!(weapon_name(0), None);
        assert_eq!(weapon_name(1366019316), None); // a raw kill asset ID, not a game item ID
        assert_eq!(weapon_kind(1), None);
    }
}
